const req = $('Search Request').first().json;
const qEmb = $('Embed Question').first().json.embedding;
const qVec = qEmb && Array.isArray(qEmb.values) ? qEmb.values : null;
if (!qVec) throw new Error('Could not embed the search question.');

const subjectFilter = String(req.subject || '').trim().toLowerCase();
const unitFilter = String(req.unit || '').trim().toLowerCase();
let topK = Number(req.top_k);
if (!Number.isFinite(topK) || topK < 1) topK = 5;
topK = Math.min(topK, 10);

const rows = $input.all().map(i => i.json).filter(r => r && r.chunk_text && r.embedding);
if (rows.length === 0) {
  return [{ json: { count: 0, results: [], message: 'No pasted notes have been saved yet.' } }];
}

const cosine = (a, b) => {
  let dot = 0, na = 0, nb = 0;
  const n = Math.min(a.length, b.length);
  for (let i = 0; i < n; i++) { dot += a[i] * b[i]; na += a[i] * a[i]; nb += b[i] * b[i]; }
  return na && nb ? dot / (Math.sqrt(na) * Math.sqrt(nb)) : 0;
};

const scored = [];
for (const r of rows) {
  if (subjectFilter && !String(r.subject || '').toLowerCase().includes(subjectFilter)) continue;
  if (unitFilter && String(r.unit || '').toLowerCase().replace(/^unit\s*/, '') !== unitFilter.replace(/^unit\s*/, '')) continue;
  let vec;
  try { vec = JSON.parse(r.embedding); } catch (e) { continue; }
  scored.push({
    score: Math.round(cosine(qVec, vec) * 1000) / 1000,
    source_type: 'pasted_text',
    source_label: 'Pasted notes - ' + r.subject + ', Unit ' + r.unit + ', Topic: ' + r.topic,
    subject: r.subject,
    unit: r.unit,
    topic: r.topic,
    note_id: r.note_id,
    chunk: (Number(r.chunk_index) + 1) + ' of ' + r.chunk_count,
    saved_at: r.saved_at,
    text: r.chunk_text,
  });
}

scored.sort((a, b) => b.score - a.score);
const results = scored.filter(s => s.score >= 0.45).slice(0, topK);
const subjects = Array.from(new Set(rows.map(r => r.subject + ' / Unit ' + r.unit + ' / ' + r.topic)));

return [{
  json: {
    count: results.length,
    results,
    saved_topics: subjects.slice(0, 50),
    message: results.length
      ? 'Found ' + results.length + ' relevant pasted-note chunk(s).'
      : 'No relevant pasted notes matched this question.',
  },
}];
